(function(){"use strict";function g(){let r=0,t=0;for(;r===0;)r=Math.random();for(;t===0;)t=Math.random();return Math.sqrt(-2*Math.log(r))*Math.cos(2*Math.PI*t)}function P(r){const{currentBtcPrice:t,horizonDays:e,nPaths:s,dailyDriftPct:C,dailyVolPct:y}=r,f=C/100,c=y/100,M=1,v=(f-.5*c*c)*M,x=c*Math.sqrt(M),i=Array.from({length:e+1},()=>[]);for(let n=0;n<s;n++)i[0].push(t);const a=[],m=30,p=Array.from({length:m},()=>[t]);for(let n=0;n<s;n++){let o=t;const u=n<m;for(let l=1;l<=e;l++){const N=g();o=o*Math.exp(v+x*N),i[l].push(o),u&&p[n].push(o)}a.push(o)}const d=[];for(let n=0;n<=e;n++){const o=[...i[n]].sort((u,l)=>u-l);d.push({day:n,p5:o[Math.floor(o.length*.05)]??t,p25:o[Math.floor(o.length*.25)]??t,p50:o[Math.floor(o.length*.5)]??t,p75:o[Math.floor(o.length*.75)]??t,p95:o[Math.floor(o.length*.95)]??t})}a.sort((n,o)=>n-o);const b=a.reduce((n,o)=>n+o,0)/(s||1),z=a[Math.floor(s/2)]??t,q=a[0]??t,D=a[s-1]??t,V=a.filter(n=>n<t).length/(s||1)*100,w=a.filter(n=>n>=t*1.2).length/(s||1)*100,A=a.filter(n=>n>=t*1.5).length/(s||1)*100,B=a[Math.floor(s*.05)]??t,G=Math.max(0,(t-B)/(t||1)*100),h=a.slice(0,Math.floor(s*.05)),L=h.length>0?h.reduce((n,o)=>n+o,0)/h.length:t,S=Math.max(0,(t-L)/(t||1)*100),E=c*Math.sqrt(365)*100,I=(Math.exp(f*365)-1)*100;return{percentileCurve:d,samplePaths:p,terminalPrices:a,terminalMean:b,terminalMedian:z,terminalMin:q,terminalMax:D,probLoss:V,probGain20:w,probGain50:A,var95Pct:G,cvar95Pct:S,annualizedVol:E,annualizedDrift:I,s0:t}}addEventListener("message",r=>{const{id:t,params:e}=r.data,s=P(e);postMessage({id:t,result:s})})})();
